INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (2, "", 576, 60005, "", 0, 0, 1, "今日の運勢は姫吉！　道を歩けば幸運に当たる、最高の吉日！　　さすがは兄様。尽善尽美、金甌無欠の強運をお持ちですね。", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (2, "", 577, 60005, "", 0, 0, 1, "今日の運勢は姫吉！　旅立ち、どこへ行くもよし！　　　　　　　新年の門出も、お兄さんと一緒です♪　冒険にしゅっぱーつ♪", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (2, "", 578, 60005, "", 0, 0, 1, "今日の運勢は姫吉！　一日三食食べれば健康運アップ！　　　　　おせち。おぞうに。もっと、たべよ？　お兄。", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (1, "", 579, 60005, "", 0, 0, 2, "今日の運勢は大吉！　あなたの趣味がもっと広がるかも！\nかんわゆ～～～いショタと～騎士きゅんもゲット～んふふ～♪", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (1, "", 580, 60005, "", 0, 0, 2, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (1, "", 581, 60005, "", 0, 0, 2, "今日の運勢は大吉！　日々の努力が実り、何事も良い方向へ！　　そんな弟くんには、お姉ちゃんのよしよしぎゅ～っをプレゼント♪", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (2, "", 582, 60005, "", 0, 0, 2, "今日の運勢は大吉！　お出かけするといいことあるかも？　　　　また一緒に、お忍びデートしてくださいね……騎士♪", 2, 0, 0);
INSERT INTO `v1_1406a20af2d2872885097334f70ee36d0d55b257e296f6aefd94ed3792847c09` VALUES (2, "", 583, 60005, "", 0, 0, 2, "今日の運勢は大吉！　転居するならあたたかい場所が吉！　　　　煉獄の世なれど、住めば都と申しんす。ゆるりときなんせ……♪", 2, 0, 0);
